#!/bin/sh
# Generated by FWShift: an AWS Network Firewall policy and its stateful rule group, created with the AWS CLI. Read the
# report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE    prints the calls, makes none (no AWS access needed)
#   CHECK=1 sh THIS_FILE      sends every call with --dry-run: AWS checks the requests and the permissions
#   sh THIS_FILE              creates the rule group and the policy
#
# AWS_OPTS adds options to every call, for example AWS_OPTS='--region eu-west-1 --profile prod'.
#
# The policy is attached to no firewall: nothing changes for any traffic until you associate it:
#   aws network-firewall associate-firewall-policy --firewall-name FIREWALL --firewall-policy-arn ARN
# A rule group or policy of the same name stops the script before anything is created; a call AWS refuses stops it
# where it is (delete what it made with aws network-firewall delete-rule-group / delete-firewall-policy and run it
# again).
set -u
DRY_RUN="${DRY_RUN:-}"
CHECK="${CHECK:-}"
AWS_OPTS="${AWS_OPTS:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'aws network-firewall' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
TMP=$(mktemp -d) || fail "mktemp"
trap 'rm -rf "$TMP"' EXIT
# free_group NAME / free_policy NAME: stop the script when one of that name exists
free_group() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-rule-group --rule-group-name "$1" --type STATEFUL $AWS_OPTS >/dev/null 2>&1; then
    fail "a rule group named $1 exists already; nothing was created"
  fi
}
free_policy() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  if aws network-firewall describe-firewall-policy --firewall-policy-name "$1" $AWS_OPTS >/dev/null 2>&1; then
    fail "a firewall policy named $1 exists already; nothing was created"
  fi
}
# group NAME CAPACITY FILE: creates a stateful rule group and prints its ARN
group() {
  if [ -n "$DRY_RUN" ]; then
    show create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3"
    printf 'arn:aws:network-firewall:dryrun:000000000000:stateful-rulegroup/%s\n' "$1"
    return 0
  fi
  if [ -n "$CHECK" ]; then
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --dry-run --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1 (dry run)"
    printf 'checked: rule group %s\n' "$1" >&2
  else
    arn=$(aws network-firewall create-rule-group --rule-group-name "$1" --type STATEFUL --capacity "$2" --rule-group "file://$3" \
      --description 'Generated by FWShift' --tags Key=fwshift,Value=generated \
      --query RuleGroupResponse.RuleGroupArn --output text $AWS_OPTS) || fail "create-rule-group $1"
    printf 'created %s\n' "$arn" >&2
  fi
  printf '%s\n' "$arn"
}
# policy NAME FILE CHECKFILE: creates the firewall policy (with CHECK, checks it without its rule groups, which a dry run
# does not create)
policy() {
  if [ -n "$DRY_RUN" ]; then show create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2"; return 0; fi
  if [ -n "$CHECK" ]; then
    aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$3" --dry-run $AWS_OPTS >/dev/null \
      || fail "create-firewall-policy $1 (dry run)"
    printf 'checked: firewall policy %s\n' "$1" >&2
    return 0
  fi
  aws network-firewall create-firewall-policy --firewall-policy-name "$1" --firewall-policy "file://$2" \
    --description 'Generated by FWShift; review the conversion report before associating it' \
    --tags Key=fwshift,Value=generated $AWS_OPTS >/dev/null || fail "create-firewall-policy $1"
  printf 'created firewall policy %s\n' "$1" >&2
}

# No rule group or policy of these names may exist.
free_group fwshift-rules
free_policy fwshift

# Rule group 1: 24 rules, in the order of the policy.
cat > "$TMP/group1.json" <<'FWSHIFT_JSON'
{
 "RuleVariables": {
  "IPSets": {
   "admins": {
    "Definition": [
     "10.10.5.0/24",
     "10.10.6.10/32",
     "2001:db8:10:5::/64"
    ]
   },
   "blocklist": {
    "Definition": [
     "198.51.100.0/24",
     "203.0.113.200/29",
     "203.0.113.208/29",
     "203.0.113.216/30",
     "203.0.113.220/32"
    ]
   },
   "inside": {
    "Definition": [
     "10.10.0.0/16",
     "2001:db8:10:5::/64"
    ]
   }
  }
 },
 "RulesSource": {
  "RulesString": "pass ip any any -> any any (msg:\"fwshift-replies\"; flow:to_client; sid:24; rev:1;)\ndrop ip $blocklist any -> any any (msg:\"global/block_bad\"; flow:to_server; sid:1; rev:1;)\ndrop ip [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> $inside any (msg:\"global/admins_continue_rd0/dmz_no_inside\"; flow:to_server; sid:2; rev:1;)\ndrop tcp [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> 2001:db8:203::10/128 443 (msg:\"global/admins_continue_vs_web6/_default_\"; flow:to_server; sid:3; rev:1;)\ndrop tcp [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> 203.0.113.10/32 443 (msg:\"global/admins_continue_vs_web/_default_\"; flow:to_server; sid:4; rev:1;)\ndrop tcp [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> 203.0.113.10/32 80 (msg:\"global/admins_continue_vs_web_http/_refused_\"; flow:to_server; sid:5; rev:1;)\ndrop udp $admins any -> 203.0.113.53/32 53 (msg:\"global/admins_continue_vs_dns/_default_\"; flow:to_server; sid:6; rev:1;)\ndrop tcp $admins any -> 203.0.113.60/32 8080 (msg:\"global/admins_continue_vs_old_app/_refused_\"; flow:to_server; sid:7; rev:1;)\ndrop ip [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> 192.168.50.0/24 any (msg:\"global/admins_continue_vs_inbound_dmz/_default_\"; flow:to_server; sid:8; rev:1;)\ndrop ip [10.10.5.0/24,10.10.6.10/32,2001:db8:10:5::/64] any -> 0.0.0.0/0 any (msg:\"global/admins_continue_vs_outbound/_default_\"; flow:to_server; sid:9; rev:1;)\nreject tcp any any -> any 23 (msg:\"global/reject_telnet\"; flow:to_server; sid:10; rev:1;)\ndrop tcp any any -> $inside 8080 (msg:\"global/inspect_irule_rd0/dmz_no_inside\"; flow:to_server; sid:11; rev:1;)\ndrop tcp any any -> 203.0.113.60/32 8080 (msg:\"global/inspect_irule_vs_old_app/_refused_\"; flow:to_server; sid:12; rev:1;)\ndrop tcp any any -> 192.168.50.0/24 8080 (msg:\"global/inspect_irule_vs_inbound_dmz/_default_\"; flow:to_server; sid:13; rev:1;)\ndrop tcp any any -> 0.0.0.0/0 8080 (msg:\"global/inspect_irule_vs_outbound/_default_\"; flow:to_server; sid:14; rev:1;)\ndrop ip any any -> $inside any (msg:\"rd0/dmz_no_inside\"; flow:to_server; sid:15; rev:1;)\ndrop tcp any any -> 2001:db8:203::10/128 443 (msg:\"vs_web6/_default_\"; flow:to_server; sid:16; rev:1;)\ndrop tcp any any -> 203.0.113.10/32 443 (msg:\"vs_web/_default_\"; flow:to_server; sid:17; rev:1;)\ndrop tcp any any -> 203.0.113.10/32 80 (msg:\"vs_web_http/_refused_\"; flow:to_server; sid:18; rev:1;)\npass udp 192.0.2.0/24 any -> 203.0.113.53/32 53 (msg:\"vs_dns/dns_from_partners\"; flow:to_server; sid:19; rev:1;)\ndrop udp any any -> 203.0.113.53/32 53 (msg:\"vs_dns/_default_\"; flow:to_server; sid:20; rev:1;)\ndrop tcp any any -> 203.0.113.60/32 8080 (msg:\"vs_old_app/_refused_\"; flow:to_server; sid:21; rev:1;)\ndrop ip any any -> 192.168.50.0/24 any (msg:\"vs_inbound_dmz/_default_\"; flow:to_server; sid:22; rev:1;)\ndrop ip any any -> 0.0.0.0/0 any (msg:\"vs_outbound/_default_\"; flow:to_server; sid:23; rev:1;)\n"
 },
 "StatefulRuleOptions": {
  "RuleOrder": "STRICT_ORDER"
 }
}
FWSHIFT_JSON
G1=$(group fwshift-rules 100 "$TMP/group1.json") || exit 1

# The policy: every packet to the stateful engine, the rule groups in strict order, then the default of the source.
cat > "$TMP/policy.json" <<FWSHIFT_JSON
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"},"StatefulRuleGroupReferences":[{"ResourceArn":"${G1}","Priority":100}]}
FWSHIFT_JSON
cat > "$TMP/policy-check.json" <<'FWSHIFT_JSON'
{"StatelessDefaultActions":["aws:forward_to_sfe"],"StatelessFragmentDefaultActions":["aws:forward_to_sfe"],"StatefulDefaultActions":["aws:drop_strict"],"StatefulEngineOptions":{"RuleOrder":"STRICT_ORDER"}}
FWSHIFT_JSON
policy fwshift "$TMP/policy.json" "$TMP/policy-check.json"

# Not written:
#   global/admins_continue>rd0/outbound/allow_dns_out@vs_dns: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   global/admins_continue>rd0/outbound/allow_dns_out@vs_outbound: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   global/admins_continue>rd0/outbound/allow_web_out@vs_outbound: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   global/admins_continue>vs_web6/web_in: the source of the rule is in zone external, and a rule of Network Firewall names no zone: give the networks behind external with --zone-network
#   global/admins_continue>vs_web/web_in: the source of the rule is in zone external, and a rule of Network Firewall names no zone: give the networks behind external with --zone-network
#   global/ping_in@vs_outbound: the source of the rule is in zone dmz, internal, and a rule of Network Firewall names no zone: give the networks behind dmz, internal with --zone-network
#   global/old_rule: disabled in the source
#   global/office_ssh@vs_outbound: schedule 'office_hours' is not converted; the rule would apply at all times; the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   global/partners_in@vs_web6: references 'partners': contains 'geo:NL' (the geolocation NL (a country or region), which FWShift cannot write as addresses)
#   global/partners_in@vs_web: references 'partners': contains 'geo:NL' (the geolocation NL (a country or region), which FWShift cannot write as addresses)
#   global/partners_in@vs_web_http: references 'partners': contains 'geo:NL' (the geolocation NL (a country or region), which FWShift cannot write as addresses)
#   global/partners_in@vs_inbound_dmz: references 'partners': contains 'geo:NL' (the geolocation NL (a country or region), which FWShift cannot write as addresses)
#   global/partners_in@vs_outbound: references 'partners': contains 'geo:NL' (the geolocation NL (a country or region), which FWShift cannot write as addresses)
#   rd0/outbound/allow_dns_out@vs_dns: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   rd0/outbound/allow_dns_out@vs_outbound: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   rd0/outbound/allow_web_out@vs_outbound: the source of the rule is in zone internal, and a rule of Network Firewall names no zone: give the networks behind internal with --zone-network
#   vs_web6/web_in: the source of the rule is in zone external, and a rule of Network Firewall names no zone: give the networks behind external with --zone-network
#   vs_web6/web6_in: the source of the rule is in zone external, and a rule of Network Firewall names no zone: give the networks behind external with --zone-network
#   vs_web/web_in: the source of the rule is in zone external, and a rule of Network Firewall names no zone: give the networks behind external with --zone-network

echo 'Done. Associate the policy with a firewall when you are ready; until then nothing changes.' >&2
